def validate_pinned_repository(repository: Path, expected_commit: str) -> str:
    """Require an exact Git commit and a clean tracked/untracked worktree."""
    commit = _git(repository, "rev-parse", "HEAD")
    if commit != expected_commit:
        raise RepositoryValidationError(
            f"repository commit mismatch: expected {expected_commit}, got {commit}"
        )
    if _git(repository, "status", "--porcelain", "--untracked-files=normal"):
        raise RepositoryValidationError("repository worktree must be clean before indexing")
    return commit

def index_repository(self, repository_path: str | Path, project_name: str | None = None) -> IndexingResult:
    """Run scanner, parser, chunker, and SQLite persistence for one repository."""
    prepared = self.prepare_repository(repository_path)
    if prepared.root_path is None:
        return IndexingResult(None, None, prepared.stats, prepared.errors)
    project_id: int | None = None
    try:
        project = self.store.replace_project_index(
            project_name or prepared.root_path.name,
            prepared.root_path,
            prepared.files,
            prepared.parse_results,
            prepared.chunks,
        )
        project_id = project.id
    except StorageError as error:
        storage_error = self._storage_error(error)
        return IndexingResult(
            project_id=project_id,
            root_path=prepared.root_path,
            stats=self._with_storage_error(prepared.stats),
            errors=tuple((*prepared.errors, storage_error)),
        )

    return IndexingResult(
        project_id=project_id,
        root_path=prepared.root_path,
        stats=prepared.stats,
        errors=prepared.errors,
    )

@dataclass(frozen=True, slots=True)
class ScanResult:
    """Complete scanner output for one repository root."""

    root_path: Path
    files: tuple[SourceFile, ...]
    errors: tuple[ScanError, ...]

def test_symlink_to_outside_repository_is_not_read(tmp_path: Path) -> None:
    outside = tmp_path.parent / f"{tmp_path.name}_outside.py"
    outside.write_text("secret = True\n", encoding="utf-8")

