                if not self._is_inside(root, absolute_path) or absolute_path.is_symlink():
                    continue
                stat = absolute_path.stat()
                files.append(
                    SourceFile(
                        relative_path=absolute_path.relative_to(root).as_posix(),
                        absolute_path=absolute_path,
                        size_bytes=stat.st_size,
                        mtime_ns=stat.st_mtime_ns,
                        sha256=self._sha256(absolute_path),
                    )
                )
                if on_file is not None:
                    on_file(len(files))
            except OSError as error:
                errors.append(self._error(root, path, error))

    return ScanResult(
        root_path=root,
        files=tuple(sorted(files, key=lambda file: file.relative_path)),
        errors=tuple(errors),
    )

def _skip_file(self, path: Path) -> bool:
    name = path.name
    return path.is_symlink() or path.suffix != ".py" or is_ignored_file(name, self.ignored_file_patterns)

def test_symlink_to_outside_repository_is_not_read(tmp_path: Path) -> None:
    outside = tmp_path.parent / f"{tmp_path.name}_outside.py"
    outside.write_text("secret = True\n", encoding="utf-8")

    try:
        (tmp_path / "outside.py").symlink_to(outside)
    except (OSError, NotImplementedError) as error:
        pytest.skip(f"Symlinks are not available: {error}")

    assert scan_paths(tmp_path) == []

def scan(
    self,
    repository_path: str | Path,
    on_file: Callable[[int], None] | None = None,
) -> ScanResult:
    """Scan a repository for eligible Python source files."""
    root = self._resolve_root(repository_path)
    files: list[SourceFile] = []
    errors: list[ScanError] = []

    def onerror(error: OSError) -> None:
        path = Path(error.filename) if error.filename else None
        errors.append(self._error(root, path, error))

    for current, dirs, filenames in os.walk(root, topdown=True, onerror=onerror, followlinks=False):
        current_path = Path(current)
        dirs[:] = self._walkable_dirs(current_path, dirs, root, errors)

        for filename in sorted(filenames):
            path = current_path / filename
            try:
                if self._skip_file(path):
                    continue
                absolute_path = path.resolve(strict=True)
                if not self._is_inside(root, absolute_path) or absolute_path.is_symlink():
                    continue
                stat = absolute_path.stat()
                files.append(
                    SourceFile(
                        relative_path=absolute_path.relative_to(root).as_posix(),
                        absolute_path=absolute_path,
                        size_bytes=stat.st_size,
                        mtime_ns=stat.st_mtime_ns,
                        sha256=self._sha256(absolute_path),
                    )
                )
                if on_file is not None:
                    on_file(len(files))
            except OSError as error:
                errors.append(self._error(root, path, error))

    return ScanResult(
        root_path=root,
        files=tuple(sorted(files, key=lambda file: file.relative_path)),
        errors=tuple(errors),
    )

def _assertion_hint(self, source_code: str, language: DocumentationLanguage) -> tuple[str, ...]:
    try:
        tree = ast.parse(textwrap.dedent(source_code))
    except SyntaxError:
        return ()
    assertion = next((node for node in ast.walk(tree) if isinstance(node, ast.Assert)), None)
    if assertion is None:
        return ()
    expression = assertion.test
    if (
        isinstance(expression, ast.Compare)
        and len(expression.ops) == 1
        and isinstance(expression.ops[0], ast.Eq)
        and len(expression.comparators) == 1
    ):
        actual = ast.unparse(expression.left)
        expected = ast.unparse(expression.comparators[0])
        sentence = (
            f"این تست بررسی می‌کند که نتیجه {actual} با {expected} برابر باشد."
            if language == "fa"
            else f"This test verifies that {actual} equals {expected}."
        )
        return (f"Trusted AST assertion: {actual} == {expected}", f"Grounded summary: {sentence}")
    return (f"Trusted AST assertion: {ast.unparse(expression)}",)

